import pandas as pd

def mean_rate(records):
    df = pd.DataFrame(records)
    df["grams"] = pd.to_numeric(df["grams"], errors="coerce")
    df = df.dropna(subset=["grams"])
    df = df.drop_duplicates(subset=["code"])
    if len(df) == 0:
        return 0.0
    return round((df["grams"] / df["boxes"]).mean(), 2)

